contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= 0);

        c.AdjustBetAmounts(amount); if (__ESBMC_reverted()) return;
        uint256 limitAfter = c.currentBetLimit(); if (__ESBMC_reverted()) return;

        assert(limitAfter == amount);
    }

    receive() external payable {}
}

