// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= 0);
        try c.AdjustBetAmounts(amount) {} catch { return; }
        uint256 limitAfter;
        try c.currentBetLimit() returns (uint256 __r) { limitAfter = __r; } catch { return; }
        assertTrue(limitAfter == amount);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
